python3 - <<'PYEOF'
import json, os, subprocess, sys
p = os.path.join(os.environ["RUN_DIR"], "publish", "tokens.json")
cmd = [
    "python3", 
    os.path.expanduser("~/.openclaw/workspace-orchestrator/skills/pipeline/update_pick_status.py"),
    "--pick-id", "190",
    "--status", "published"
]
if os.path.exists(p):
    try:
        t = json.load(open(p))
        if t.get("tokens_in") is not None:
            cmd += ["--tokens-in", str(int(t["tokens_in"]))]
        if t.get("tokens_out") is not None:
            cmd += ["--tokens-out", str(int(t["tokens_out"]))]
        if t.get("tokens_total") is not None:
            cmd += ["--tokens-total", str(int(t["tokens_total"]))]
        if t.get("cost_usd") is not None:
            cmd += ["--cost-usd", str(float(t["cost_usd"]))]
        by_model = t.get("by_model")
        if isinstance(by_model, dict) and by_model:
            cmd += ["--tokens-by-model", json.dumps(by_model, ensure_ascii=False)]
    except Exception as e:
        print("Error parsing tokens:", e)

res = subprocess.run(cmd, capture_output=True, text=True)
print("STDOUT:", res.stdout)
print("STDERR:", res.stderr)
PYEOF
